        afterA = parse_arp(outA)
        afterB = parse_arp(outB)
        afterGlobal = parse_arp(outGlobalScope)
        output = 'clear: {}\nVRF-A:\n{}\nVRF-B:\n{}\nshow arp:\n{}'.format(clearOut.strip(), outA, outB, outGlobal)
        self.log('OBSERVED: {}'.format(output))

